input.command:
$codex = "$env:USERPROFILE\.codex"
$ts = Get-Date -Format "yyyyMMdd_HHmmss"
$backup = Join-Path $codex "backup_$ts"
New-Item -ItemType Directory -Force -Path $backup | Out-Null

$files = @(
  "state_5.sqlite",
  "state_5.sqlite-wal",
  "state_5.sqlite-shm"
)

Write-Host "Backup dir: $backup"
foreach ($f in $files) {
  $src = Join-Path $codex $f
  if (Test-Path $src) {
    Move-Item -Path $src -Destination (Join-Path $backup "$f.bak") -Force
    Write-Host "Moved: $f"
  } else {
    Write-Host "Skip (not found): $f"
  }
}

Write-Host "--- Remaining state files ---"
Get-ChildItem $codex -Filter "state_*" | Select-Object Name,Length,LastWriteTime

Write-Host "--- Integrity check (should be absent) ---"
if (Test-Path (Join-Path $codex "state_5.sqlite")) { Write-Host "state_5.sqlite still exists!" } else { Write-Host "state_5.sqlite removed successfully" }
